* 'scan_ps()' - Scan a string for the next PS object.
 */

static _cups_ps_obj_t   *               /* O  - New object or NULL on EOF */
scan_ps(_cups_ps_stack_t *st,           /* I  - Stack */
        char             **ptr)         /* IO - String pointer */
{
  _cups_ps_obj_t        obj;            /* Current object */
  char                  *start,         /* Start of object */
                        *cur,           /* Current position */
                        *valptr,        /* Pointer into value string */
                        *valend;        /* End of value string */
  int                   parens;         /* Parenthesis nesting level */


 /*
  * Skip leading whitespace...
  */

  for (cur = *ptr; *cur; cur ++)
  {
    if (*cur == '%')
    {
     /*
      * Comment, skip to end of line...
      */

      for (cur ++; *cur && *cur != '\n' && *cur != '\r'; cur ++);

      if (!*cur)
        cur --;
    }
    else if (!isspace(*cur & 255))
      break;
  }

  if (!*cur)
  {
    *ptr = NULL;

    return (NULL);
  }

 /*
  * See what we have...
  */

  memset(&obj, 0, sizeof(obj));

  switch (*cur)
  {
    case '(' :                          /* (string) */
        obj.type = CUPS_PS_STRING;
        start    = cur;

        for (cur ++, parens = 1, valptr = obj.value.string,
                 valend = obj.value.string + sizeof(obj.value.string) - 1;
             *cur;
             cur ++)
        {
          if (*cur == ')' && parens == 1)
            break;

          if (*cur == '(')
            parens ++;
          else if (*cur == ')')
            parens --;

          if (valptr >= valend)
          {
            *ptr = start;

            return (NULL);
          }

          if (*cur == '\\')
          {
           /*
            * Decode escaped character...
            */

            cur ++;

            if (*cur == 'b')
              *valptr++ = '\b';
            else if (*cur == 'f')
              *valptr++ = '\f';
            else if (*cur == 'n')
              *valptr++ = '\n';
            else if (*cur == 'r')
              *valptr++ = '\r';
            else if (*cur == 't')
              *valptr++ = '\t';
            else if (*cur >= '0' && *cur <= '7')
            {
              int ch = *cur - '0';

              if (cur[1] >= '0' && cur[1] <= '7')
              {
                cur ++;
                ch = (ch << 3) + *cur - '0';
              }

              if (cur[1] >= '0' && cur[1] <= '7')
              {
                cur ++;
                ch = (ch << 3) + *cur - '0';
              }

              *valptr++ = (char)ch;
            }
            else if (*cur == '\r')
            {
              if (cur[1] == '\n')
                cur ++;
            }
            else if (*cur != '\n')
              *valptr++ = *cur;
          }
          else
            *valptr++ = *cur;
        }

        if (*cur != ')')
        {
          *ptr = start;

          return (NULL);
        }

        cur ++;
        break;

